insert into public.docs (col, id, data) values
  ('news', 'n2011-tranh', '{"kind": "art", "title": "Phong trào vẽ tranh “Mái trường và thầy cô” chào mừng Ngày Nhà giáo Việt Nam 20/11", "body": "Mỗi bạn vẽ 1 bức tranh về mái trường hoặc về thầy cô của em để chào mừng ngày 20/11.\nCách tham gia: chụp ảnh bức tranh thật thẳng, đủ sáng rồi gửi ở Phòng tranh 3D (dãy C). Đặt tên tranh và viết vài dòng giới thiệu.\nHạn nộp: hết ngày 15/11. Tranh được thầy cô duyệt sẽ treo trong Phòng tranh 3D để cả trường cùng xem.", "start": "2026-10-27", "end": "2026-11-15", "mul": 2, "gift": "Tranh đẹp được chọn làm Tranh tiêu biểu (khung vàng) trong Phòng tranh 3D", "grades": "all", "pin": true, "at": 1793085600000}'::jsonb),
  ('news', 'n2011-rcv', '{"kind": "rcv", "title": "Ngày hội Rung chuông vàng chào mừng Ngày Nhà giáo Việt Nam 20/11", "body": "Ngày 19/11, mời tất cả các bạn vào Hội trường (phía đông sân trường), đi tới bục MC và bấm Đăng kí thi để tham gia Rung chuông vàng.\nTrả lời đúng để trụ lại sàn đấu, sai thì rời sàn. Thi trong đúng ngày 19/11 được nhân đôi điểm thưởng.", "start": "2026-11-19", "end": "2026-11-19", "mul": 2, "gift": "Bạn trụ lại đến câu cuối cùng được tuyên dương trước toàn trường", "grades": "all", "pin": true, "at": 1793085600001}'::jsonb),
  ('art', 'theme-2026-10', '{"kind": "theme", "month": "2026-10", "title": "Mái trường và thầy cô – chào mừng 20/11", "desc": "Vẽ ngôi trường của em hoặc thầy cô em yêu quý. Hạn nộp hết ngày 15/11.", "at": 1793085600002}'::jsonb),
